        private static readonly System.Collections.Generic.Dictionary<string, GunSpec> _byId;
        private static readonly System.Collections.Generic.Dictionary<string, GunExtended> _extById;

        static GunData()
        {
            _byId = new System.Collections.Generic.Dictionary<string, GunSpec>(Guns.Length);
            _extById = new System.Collections.Generic.Dictionary<string, GunExtended>(Extended.Length);
            for (int i = 0; i < Guns.Length; i++) _byId[Guns[i].Id] = Guns[i];
            for (int i = 0; i < Extended.Length; i++) _extById[Extended[i].Id] = Extended[i];
        }

        public static GunSpec Get(string id)
        {
            GunSpec g;
            return _byId.TryGetValue(id, out g) ? g : default(GunSpec);
        }

        public static GunExtended GetExtended(string id)
        {
            GunExtended e;
            return _extById.TryGetValue(id, out e) ? e : default(GunExtended);
        }

        public static bool Has(string id) { return _byId.ContainsKey(id); }

        public static string FullName(GunSpec g)
        {
            GunExtended e = GetExtended(g.Id);
            return e.Alias.Length > 0 ? g.Name + " \"" + e.Alias + "\"" : g.Name;
        }

        public static string SlotOf(GunClass c)
        {
            if (c == GunClass.Pistol || c == GunClass.Launcher) return "secondary";
            if (c == GunClass.Melee) return "melee";
            return "primary";
        }

        public static string ClassDisplayName(GunClass c)
        {
            switch (c)
            {
                case GunClass.AssaultRifle: return "Assault Rifle";
                case GunClass.SMG: return "SMG";
                case GunClass.LMG: return "LMG";
                case GunClass.Sniper: return "Sniper";
                case GunClass.Marksman: return "Marksman";
                case GunClass.Shotgun: return "Shotgun";
                case GunClass.Pistol: return "Pistol";
                case GunClass.Launcher: return "Launcher";
                default: return "Melee";
            }
        }

        /// <summary>Damage with linear falloff between near and far, min 35% past far.</summary>
        public static float DamageAtRange(GunSpec g, float dist)
        {
            GunExtended e = GetExtended(g.Id);
            if (dist <= e.RangeNear) return g.Damage;
            if (dist >= g.Range) return g.Damage * 0.35f;
            float t = (dist - e.RangeNear) / Mathf.Max(g.Range - e.RangeNear, 0.01f);
            return g.Damage * Mathf.Lerp(1f, 0.35f, t);
        }

        public struct StkInfo { public int Body, Head, ArmoredBody, ArmoredHead; }

        /// <summary>Shots-to-kill vs 100 HP (body) and 250 armored HP, close range, all landing.</summary>
        public static StkInfo ShotsToKillFull(GunSpec g)
        {
            GunExtended e = GetExtended(g.Id);
            float dmg = g.Damage;
            if (g.Class == GunClass.Shotgun) dmg *= Mathf.Max(e.Pellets, 1);
            if (g.Class == GunClass.Launcher)
                return new StkInfo { Body = 1, Head = 1, ArmoredBody = 1, ArmoredHead = 1 };
            if (dmg <= 0f)
                return new StkInfo { Body = 99, Head = 99, ArmoredBody = 99, ArmoredHead = 99 };
            int body = Mathf.CeilToInt(100f / dmg);
            int head = Mathf.CeilToInt(100f / (dmg * g.HeadMult));
            int abody = Mathf.CeilToInt(250f / dmg);
            int ahead = Mathf.CeilToInt(250f / (dmg * g.HeadMult));
            return new StkInfo { Body = body, Head = head, ArmoredBody = abody, ArmoredHead = ahead };
        }

        /// <summary>Contract STK: shots-to-kill for one hit profile.</summary>
        public static int ShotsToKill(GunSpec g, bool headshot, bool armored)
        {
            StkInfo s = ShotsToKillFull(g);
            if (headshot) return armored ? s.ArmoredHead : s.Head;
            return armored ? s.ArmoredBody : s.Body;
        }

        /// <summary>Short STK label for the HUD weapon panel, e.g. "4 SHOTS · 3 HEAD".</summary>
        public static string StkLabel(GunSpec g)
        {
            if (g.Class == GunClass.Launcher) return "1 BLAST KILL";
            StkInfo s = ShotsToKillFull(g);
            if (g.Class == GunClass.Melee) return s.Body + " SWINGS";
            return s.Body + " SHOTS · " + s.Head + " HEAD";
        }

        /// <summary>Tier-weighted random gun id. Higher tier -> deadlier classes.</summary>
        public static string RollGun(int tier, System.Random rng)
        {
            var ids = new System.Collections.Generic.List<string>();
            var weights = new System.Collections.Generic.List<double>();
            foreach (GunSpec g in Guns)
            {
                double w = 1.0;
                switch (g.Class)
                {
                    case GunClass.Pistol:
                    case GunClass.Melee: w = tier <= 1 ? 3.0 : 0.4; break;
                    case GunClass.Shotgun:
                    case GunClass.SMG: w = tier <= 2 ? 2.5 : 1.0; break;
                    case GunClass.AssaultRifle: w = tier <= 1 ? 1.5 : 2.5; break;
                    case GunClass.Marksman: w = tier <= 1 ? 0.4 : 2.0; break;
                    case GunClass.LMG:
                    case GunClass.Sniper: w = tier <= 2 ? 0.3 : 2.2; break;
                    case GunClass.Launcher: w = tier <= 2 ? 0.15 : 1.2; break;
                }
                if (tier == 0 && g.Class == GunClass.Launcher) w = 0.0;
                if (g.Id == "rp7" && tier >= 4) w = 2.4;
                if (w <= 0.0) continue;
                ids.Add(g.Id); weights.Add(w);
            }
            double total = 0.0;
            for (int i = 0; i < weights.Count; i++) total += weights[i];
            if (total <= 0.0) return "m5";
            double r = rng.NextDouble() * total;
            for (int i = 0; i < ids.Count; i++)
            {
                r -= weights[i];
                if (r <= 0.0) return ids[i];
            }
            return "m5";
        }

        /// <summary>Default attachments pre-equipped by loot tier (grey->orange).</summary>
        public static string[] TierAttachments(int tier, System.Random rng)
        {
            var outList = new System.Collections.Generic.List<string>();
            if (tier >= 3)
            {
                string[] cands = { "reddot", "foregrip", "extended", "compensator" };
                outList.Add(cands[rng.Next(cands.Length)]);
            }
            if (tier >= 4)
            {
                string[] c2 = { "holo", "suppressor", "laser", "extended" };
                string pick = c2[rng.Next(c2.Length)];
                if (!outList.Contains(pick)) outList.Add(pick);
            }
            if (tier >= 5 && !outList.Contains("suppressor")) outList.Add("suppressor");
            return outList.ToArray();
        }
    }
